// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListAccounts The user's accounts
	// (GET /accounts)
	ListAccounts(ctx context.Context, request ListAccountsRequestObject) (ListAccountsResponseObject, error)
	// CreateAccount Create an account
	// (POST /accounts)
	CreateAccount(ctx context.Context, request CreateAccountRequestObject) (CreateAccountResponseObject, error)
	// DeleteAccount Delete an account with its imports and transactions
	// (DELETE /accounts/{id})
	DeleteAccount(ctx context.Context, request DeleteAccountRequestObject) (DeleteAccountResponseObject, error)
	// UpdateAccount Change an account
	// (PATCH /accounts/{id})
	UpdateAccount(ctx context.Context, request UpdateAccountRequestObject) (UpdateAccountResponseObject, error)
	// Login Sign in
	// (POST /auth/login)
	Login(ctx context.Context, request LoginRequestObject) (LoginResponseObject, error)
	// Logout Sign out
	// (POST /auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// Signup Create an account and sign in
	// (POST /auth/signup)
	Signup(ctx context.Context, request SignupRequestObject) (SignupResponseObject, error)
	// ListCategories Categories with counts and colour slots
	// (GET /categories)
	ListCategories(ctx context.Context, request ListCategoriesRequestObject) (ListCategoriesResponseObject, error)
	// LoadDemoData Create a demo account with the generated demo year
	// (POST /demo-data)
	LoadDemoData(ctx context.Context, request LoadDemoDataRequestObject) (LoadDemoDataResponseObject, error)
	// ListDuplicates Duplicate groups with every version (the duplicates window)
	// (GET /duplicates)
	ListDuplicates(ctx context.Context, request ListDuplicatesRequestObject) (ListDuplicatesResponseObject, error)
	// ResetDuplicate Back to the default merge ("Merge again")
	// (DELETE /duplicates/{accountId}/{fingerprint})
	ResetDuplicate(ctx context.Context, request ResetDuplicateRequestObject) (ResetDuplicateResponseObject, error)
	// DecideDuplicate Use one version, or keep both
	// (PUT /duplicates/{accountId}/{fingerprint})
	DecideDuplicate(ctx context.Context, request DecideDuplicateRequestObject) (DecideDuplicateResponseObject, error)
	// ListGroups Groups with their stats
	// (GET /groups)
	ListGroups(ctx context.Context, request ListGroupsRequestObject) (ListGroupsResponseObject, error)
	// CreateGroup Create a group
	// (POST /groups)
	CreateGroup(ctx context.Context, request CreateGroupRequestObject) (CreateGroupResponseObject, error)
	// DeleteGroup Delete a group (its labels only, never transactions)
	// (DELETE /groups/{id})
	DeleteGroup(ctx context.Context, request DeleteGroupRequestObject) (DeleteGroupResponseObject, error)
	// UpdateGroup Rename or recolour a group
	// (PATCH /groups/{id})
	UpdateGroup(ctx context.Context, request UpdateGroupRequestObject) (UpdateGroupResponseObject, error)
	// ListImports Imports, newest first
	// (GET /imports)
	ListImports(ctx context.Context, request ListImportsRequestObject) (ListImportsResponseObject, error)
	// UploadImport Upload a bank export and get a preview
	// (POST /imports)
	UploadImport(ctx context.Context, request UploadImportRequestObject) (UploadImportResponseObject, error)
	// DeleteImport Delete an import (cancel a preview, or remove a committed import)
	// (DELETE /imports/{id})
	DeleteImport(ctx context.Context, request DeleteImportRequestObject) (DeleteImportResponseObject, error)
	// GetImport One import
	// (GET /imports/{id})
	GetImport(ctx context.Context, request GetImportRequestObject) (GetImportResponseObject, error)
	// UpdateImport Change the account, mapping or options of a previewed import
	// (PATCH /imports/{id})
	UpdateImport(ctx context.Context, request UpdateImportRequestObject) (UpdateImportResponseObject, error)
	// CommitImport Commit a previewed import
	// (POST /imports/{id}/commit)
	CommitImport(ctx context.Context, request CommitImportRequestObject) (CommitImportResponseObject, error)
	// GetImportFile The original file
	// (GET /imports/{id}/file)
	GetImportFile(ctx context.Context, request GetImportFileRequestObject) (GetImportFileResponseObject, error)
	// ListImportLines Decoded records of the file with their status (header-row picker)
	// (GET /imports/{id}/lines)
	ListImportLines(ctx context.Context, request ListImportLinesRequestObject) (ListImportLinesResponseObject, error)
	// ReprocessImport Re-read a committed import with a new mapping or options
	// (POST /imports/{id}/reprocess)
	ReprocessImport(ctx context.Context, request ReprocessImportRequestObject) (ReprocessImportResponseObject, error)
	// ListImportRows Staged rows of an import
	// (GET /imports/{id}/rows)
	ListImportRows(ctx context.Context, request ListImportRowsRequestObject) (ListImportRowsResponseObject, error)
	// InsightCashflow Money in and out per month
	// (POST /insights/cashflow)
	InsightCashflow(ctx context.Context, request InsightCashflowRequestObject) (InsightCashflowResponseObject, error)
	// InsightCategories Spending by category, largest first
	// (POST /insights/categories)
	InsightCategories(ctx context.Context, request InsightCategoriesRequestObject) (InsightCategoriesResponseObject, error)
	// InsightDaily Spending per day for the calendar
	// (POST /insights/daily)
	InsightDaily(ctx context.Context, request InsightDailyRequestObject) (InsightDailyResponseObject, error)
	// InsightPace Cumulative spending through a month vs a comparison
	// (POST /insights/pace)
	InsightPace(ctx context.Context, request InsightPaceRequestObject) (InsightPaceResponseObject, error)
	// InsightPayees Top payees by spending
	// (POST /insights/payees)
	InsightPayees(ctx context.Context, request InsightPayeesRequestObject) (InsightPayeesResponseObject, error)
	// InsightSummary Summary card (spent, income, net, average per day, largest expense)
	// (POST /insights/summary)
	InsightSummary(ctx context.Context, request InsightSummaryRequestObject) (InsightSummaryResponseObject, error)
	// DeleteMe Delete the account and all of its data
	// (DELETE /me)
	DeleteMe(ctx context.Context, request DeleteMeRequestObject) (DeleteMeResponseObject, error)
	// GetMe The signed-in user
	// (GET /me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// UpdateMe Change the display name
	// (PATCH /me)
	UpdateMe(ctx context.Context, request UpdateMeRequestObject) (UpdateMeResponseObject, error)
	// ExportMe Download all of the user's data
	// (GET /me/export)
	ExportMe(ctx context.Context, request ExportMeRequestObject) (ExportMeResponseObject, error)
	// ChangePassword Change the password
	// (POST /me/password)
	ChangePassword(ctx context.Context, request ChangePasswordRequestObject) (ChangePasswordResponseObject, error)
	// ListSessions The user's active sessions
	// (GET /me/sessions)
	ListSessions(ctx context.Context, request ListSessionsRequestObject) (ListSessionsResponseObject, error)
	// RevokeSession Sign out one session
	// (DELETE /me/sessions/{id})
	RevokeSession(ctx context.Context, request RevokeSessionRequestObject) (RevokeSessionResponseObject, error)
	// GetMeta Public instance information
	// (GET /meta)
	GetMeta(ctx context.Context, request GetMetaRequestObject) (GetMetaResponseObject, error)
	// GetPreferences The user's UI preferences
	// (GET /preferences)
	GetPreferences(ctx context.Context, request GetPreferencesRequestObject) (GetPreferencesResponseObject, error)
	// PutPreferences Replace the UI preferences
	// (PUT /preferences)
	PutPreferences(ctx context.Context, request PutPreferencesRequestObject) (PutPreferencesResponseObject, error)
	// BulkUpdateTransactions Set or remove the group of many transactions
	// (POST /transactions/bulk)
	BulkUpdateTransactions(ctx context.Context, request BulkUpdateTransactionsRequestObject) (BulkUpdateTransactionsResponseObject, error)
	// DistinctValues A column's values with counts (the value checklist)
	// (POST /transactions/distinct)
	DistinctValues(ctx context.Context, request DistinctValuesRequestObject) (DistinctValuesResponseObject, error)
	// ExportTransactions The filtered, sorted rows as CSV
	// (POST /transactions/export)
	ExportTransactions(ctx context.Context, request ExportTransactionsRequestObject) (ExportTransactionsResponseObject, error)
	// TransactionRange Ids and amounts of a range of the ordered result (range selection)
	// (POST /transactions/ids)
	TransactionRange(ctx context.Context, request TransactionRangeRequestObject) (TransactionRangeResponseObject, error)
	// QueryTransactions A window of transactions with totals
	// (POST /transactions/query)
	QueryTransactions(ctx context.Context, request QueryTransactionsRequestObject) (QueryTransactionsResponseObject, error)
	// GetTransaction One transaction with its raw fields and source imports
	// (GET /transactions/{id})
	GetTransaction(ctx context.Context, request GetTransactionRequestObject) (GetTransactionResponseObject, error)
	// UpdateTransaction Set the category or the note
	// (PATCH /transactions/{id})
	UpdateTransaction(ctx context.Context, request UpdateTransactionRequestObject) (UpdateTransactionResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

